import React, { useContext } from 'react';
import { UserContext } from '../context/UserContext';

const Eliminar = ({ usuario }) => {
    const { deleteUser } = useContext(UserContext);

    const handleDelete = async () => {
        if (window.confirm("¿Estás seguro de que deseas eliminar este usuario?")) {
            // Realizamos la solicitud al backend (PHP) para eliminar el usuario
            try {
                const response = await fetch(`http://localhost/tu_ruta_al_script_php/eliminar.php?id=${usuario}`, {
                    method: 'DELETE',  // Usamos el método DELETE para eliminar
                });

                const result = await response.json();

                if (result.success) {
                    deleteUser(usuario);  // Eliminamos del estado local
                    console.log(`Usuario con ID ${usuario} eliminado.`);
                } else {
                    console.log(`Error al eliminar usuario: ${result.message}`);
                }
            } catch (error) {
                console.error("Error en la solicitud:", error);
            }
        }
    };

    return (
        <button onClick={handleDelete} style={{ color: 'red' }}>
            Eliminar
        </button>
    );
};

export default Eliminar;
